const input = $input.first().json;

// 1. Read research configuration
const brand = String(input.brand_name || "").trim();
const country = String(input.target_country || "").trim();
const competitorNames = String(input.competitor_names || "");
const objective = String(input.marketing_objective || "").trim();
const requestedLimit = Number(input.ads_limit || 5);

const adLibraryUrl = String(input.ad_library_url || "").trim();

// 2. Validate research configuration
const errors = [];

if (!brand) errors.push("Brand name is required.");
if (!country) errors.push("Target country is required.");
if (!objective) errors.push("Marketing objective is required.");

if (!Number.isFinite(requestedLimit) || requestedLimit < 1) {
  errors.push("Number of ads must be at least 1.");
}

if (errors.length) {
  throw new Error("AdMind validation failed: " + errors.join(" "));
}

// 3. Validate Meta Ad Library URL
let urlStatus = "Not provided";

if (adLibraryUrl) {
  if (!/facebook\.com\/ads\/library/i.test(adLibraryUrl)) {
    throw new Error("Please provide a valid Facebook Ad Library URL.");
  }

  urlStatus = "Valid Meta Ad Library URL";
}

// 4. Normalize competitor names
const competitors = [
  ...new Set(
    competitorNames
      .split(",")
      .map(name => name.trim().replace(/\s+/g, " "))
      .filter(Boolean)
  )
];

// 5. Read multiple ads from JSON textarea
let ads = [];

const adsJson = String(input.ads_json || "").trim();

if (adsJson) {
  try {
    ads = JSON.parse(adsJson);
  } catch (error) {
    throw new Error(
      "Invalid Ads JSON. Check the JSON format: " + error.message
    );
  }

  if (!Array.isArray(ads)) {
    throw new Error("Multiple Ads Data must contain a JSON array.");
  }
}

// 6. Backward compatibility: use the original single-ad form
if (!ads.length) {
  ads = [{
    advertiser: input.advertiser,
    adId: input.ad_id,
    headline: input.headline,
    primaryText: input.primary_text,
    cta: input.cta,
    adFormat: input.ad_format,
    creativeDescription: input.creative_description
  }];
}

// 7. Apply analysis limit
const analysisLimit = Math.min(requestedLimit, 10);
ads = ads.slice(0, analysisLimit);

// 8. Validate and normalize every advertisement
const normalizedAds = ads.map((ad, index) => {
  const advertiser = String(ad.advertiser || "").trim();
  const adId = String(ad.adId || ad.ad_id || "").trim();
  const headline = String(ad.headline || "").trim();

  const rawPrimaryText = String(
    ad.primaryText || ad.primary_text || ""
  ).trim();

  const hasVerifiedPrimaryText =
    rawPrimaryText &&
    !rawPrimaryText.toLowerCase().includes("enter exact visible text") &&
    !rawPrimaryText.toLowerCase().includes("not available");

  const primaryText = hasVerifiedPrimaryText
    ? rawPrimaryText
    : "Not available – primary ad text could not be verified.";

  if (!advertiser || !adId || !headline) {
    throw new Error(
      `Advertisement ${index + 1} requires advertiser, adId and headline.`
    );
  }

  return {
    adNumber: index + 1,
    advertiser,
    adId,
    headline,
    primaryText,
    primaryTextVerified: Boolean(hasVerifiedPrimaryText),
    cta: String(ad.cta || "Not provided").trim(),
    adFormat: String(ad.adFormat || ad.ad_format || "Unknown").trim(),
    creativeDescription: String(
      ad.creativeDescription || ad.creative_description || ""
    ).trim(),
    adLibraryUrl:
      `https://www.facebook.com/ads/library/?id=${encodeURIComponent(adId)}`
  };
});

// 9. Build research configuration
const researchConfig = {
  brand,
  country,
  competitors,
  marketingObjective: objective,
  requestedAds: requestedLimit,
  analysisLimit,
  actualAdsSubmitted: normalizedAds.length,
  adLibraryUrl,
  adLibraryUrlStatus: urlStatus,

  analysisDimensions: [
    "Hook and opening message",
    "Core advertising message",
    "Call to action",
    "Audience pain point",
    "Emotional appeal",
    "Marketing angle",
    "Creative format",
    "Funnel stage",
    "Evidence and persuasion"
  ],

  intelligenceModules: [
    "Creative DNA Extraction",
    "Competitor Strategy Analysis",
    "Explainable Creative Quality Index",
    "Multi-Ad Creative Ranking",
    "Creative Opportunity Finder",
    "Original Campaign Concept Generator"
  ]
};

// 10. Return structured multi-ad data
return [{
  json: {
    status: "validated",
    project: "AdMind",
    researchConfig,
    ads: normalizedAds,

    validation: {
      passed: true,
      competitorCount: competitors.length,
      adsSubmitted: normalizedAds.length,
      analysisLimit,
      urlStatus,
      allAdsValidated: true,
      processingMode: "Multi-ad manual research"
    }
  }
}];

/**
 * AdMind – Competitor Search Preparation
 * Version: 1.1
 * Purpose: Generate Meta Ad Library search URLs
 * and prepare Apify actor input.
 */

// 1. Get validated input from the previous node
const data = $input.first().json;
const config = data.researchConfig;

// 2. Validate incoming research configuration
if (!config) {
  throw new Error(
    "Research configuration not found. Check the previous node."
  );
}

if (!config.brand || !config.country) {
  throw new Error(
    "Brand name and target country are required."
  );
}

// 3. Map country names to Meta Ad Library country codes
const countryCodes = {
  "india": "IN",
  "united states": "US",
  "usa": "US",
  "united kingdom": "GB",
  "uk": "GB",
  "canada": "CA",
  "australia": "AU"
};

const countryKey = config.country.toLowerCase().trim();

const countryCode = countryCodes[countryKey] || "ALL";

// 4. Prepare competitor search terms
const searchTerms = config.competitors.length > 0
  ? config.competitors
  : [config.brand];

// 5. Generate Meta Ad Library search URLs
// Avoid URLSearchParams for Code node compatibility.

let startUrls = [];

if (config.adLibraryUrl) {

  startUrls = [
    {
      url: config.adLibraryUrl
    }
  ];

} else {

  startUrls = searchTerms.map(competitor => {

    const query = [
      ["active_status", "active"],
      ["ad_type", "all"],
      ["country", countryCode],
      ["q", competitor],
      ["search_type", "keyword_unordered"],
      ["media_type", "all"]
    ]
      .map(([key, value]) => {
        return key + "=" + encodeURIComponent(value);
      })
      .join("&");

    return {
      url:
        "https://www.facebook.com/ads/library/?" +
        query
    };

  });

}

// 6. Apply a safe research limit
const analysisLimit = Math.min(
  Math.max(Number(config.analysisLimit) || 5, 1),
  10
);

// 7. Prepare Apify actor input
const actorInput = {
  startUrls: startUrls,
  resultsLimit: analysisLimit,
  maxItems: analysisLimit,
  activeStatus: "active",
  sorting: "relevancy_monthly_grouped",
  isDetailsPerAd: false,
  runTag: "admind-english-learning-research"
};

// 8. Return structured search preparation output
return [
  {
    json: {

      project: "AdMind",

      stage: "competitor_search_preparation",

      status: "ready",

      research: {
        brand: config.brand,
        country: config.country,
        countryCode: countryCode,
        competitors: searchTerms,
        marketingObjective: config.marketingObjective
      },

      collection: {
        searchCount: startUrls.length,
        totalAdLimit: analysisLimit,
        actorId: "apidojo/facebook-ads-scraper"
      },

      searchTerms: searchTerms,

      startUrls: startUrls,

      actorInput: actorInput

    }
  }
];

const items = $input.all();

if (!items.length) {
  throw new Error("No advertisements received from Split Out.");
}

return items.map((item, index) => {
  const input = item.json;

  // Read the individual advertisement from Split Out
  const ad = input.ads || {};

  if (!ad.advertiser || !ad.headline || !ad.adId) {
    throw new Error(
      `Advertisement ${index + 1} is missing advertiser, headline or ad ID.`
    );
  }

  // Validate primary ad text
  const rawPrimaryText = String(ad.primaryText || "").trim();

  const hasVerifiedPrimaryText =
    rawPrimaryText &&
    !rawPrimaryText.toLowerCase().includes("enter exact visible text") &&
    !rawPrimaryText.toLowerCase().includes("not available");

  const primaryText = hasVerifiedPrimaryText
    ? rawPrimaryText
    : "Not available – primary ad text could not be verified.";

  // Generate individual Meta Ad Library URL
  const individualAdUrl =
    `https://www.facebook.com/ads/library/?id=${encodeURIComponent(ad.adId)}`;

  return {
    json: {
      project: "AdMind",

      dataSource: "Manual Meta Ad Library Research",

      researchConfig: input.researchConfig || {},

      ad: {
        adNumber: ad.adNumber || index + 1,
        advertiser: ad.advertiser,
        adId: ad.adId,
        headline: ad.headline,
        primaryText,
        primaryTextVerified: Boolean(hasVerifiedPrimaryText),
        cta: ad.cta || "Not provided",
        adFormat: ad.adFormat || "Unknown",
        creativeDescription: ad.creativeDescription || "",
        adLibraryUrl: individualAdUrl
      },

      processingStatus: "Normalized"
    }
  };
});

