const inputs = $input.all();

const originalItems = $("07 – Normalize & Filter Ad Creatives").all();

if (!inputs.length) {
  throw new Error("No AI analysis received.");
}

return inputs.map((item, index) => {
  const input = item.json;

  // 1. Extract AI response
  let analysis =
    input.choices?.[0]?.message?.content ||
    input.body?.choices?.[0]?.message?.content ||
    input.text ||
    input.content;

  if (!analysis) {
    throw new Error(`AI response missing for advertisement ${index + 1}.`);
  }

  // 2. Clean and parse AI JSON
  if (typeof analysis === "string") {
    analysis = analysis
      .replace(/^```json\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();

   // Remove known malformed properties sometimes generated by the AI model
analysis = analysis.replace(
  /^\s*(?:广大"|pocos|certainly)\s*:\s*.*?,?\s*$/gm,
  ""
);

    // Extract the JSON object
    const start = analysis.indexOf("{");
    const end = analysis.lastIndexOf("}");

    if (start === -1 || end === -1 || end < start) {
      throw new Error(
        `No valid JSON object found for advertisement ${index + 1}.`
      );
    }

    analysis = analysis.slice(start, end + 1);

    try {
      analysis = JSON.parse(analysis);
    } catch (error) {
      throw new Error(
        `Could not parse AI analysis for advertisement ${index + 1}: ${error.message}`
      );
    }
  }

  if (!analysis || typeof analysis !== "object") {
    throw new Error(`Invalid AI analysis for advertisement ${index + 1}.`);
  }

  // 3. Retrieve matching normalized advertisement
  const original = originalItems[index]?.json;

  if (!original) {
    throw new Error(
      `Original advertisement data missing for item ${index + 1}.`
    );
  }

  const ad = original.ad || {};
  const research = original.researchConfig || {};

  // 4. Define scoring criteria
  const criteria = [
    { name: "Hook strength", weight: 25, field: "hook" },
    { name: "Message clarity", weight: 20, field: "core_message" },
    { name: "Persuasiveness", weight: 20, field: "persuasion_evidence" },
    { name: "CTA effectiveness", weight: 15, field: "cta" },
    { name: "Creative execution", weight: 10, field: "strengths" },
    { name: "Audience relevance", weight: 10, field: "audience_pain_point" }
  ];

  // 5. Calculate evidence coverage
  const scores = criteria.map(criterion => {
    const value = analysis[criterion.field];

    const known =
      value !== undefined &&
      value !== null &&
      value !== "" &&
      value !== "Unknown" &&
      !(Array.isArray(value) && value.length === 0);

    return {
      criterion: criterion.name,
      weight: criterion.weight,
      evidenceAvailable: known,
      status: known
        ? "Evidence available"
        : "Insufficient evidence"
    };
  });

  const evidenceCoverage = scores
    .filter(score => score.evidenceAvailable)
    .reduce((sum, score) => sum + score.weight, 0);

  // 6. Return one result per advertisement
  return {
    json: {
      project: "AdMind",

      adNumber: ad.adNumber || index + 1,

      brand:
        analysis.brand ||
        ad.advertiser ||
        research.brand ||
        "Unknown",

      advertiser: ad.advertiser || "Unknown",

      adId: ad.adId || "Unknown",

      headline: ad.headline || "Unknown",

      adFormat: ad.adFormat || "Unknown",

      adLibraryUrl: ad.adLibraryUrl || "Unknown",

      marketingObjective:
        research.marketingObjective || "Unknown",

      creativeQualityIndex: evidenceCoverage,

      maximumScore: 100,

      evidenceCoverage,

      scoringMethod:
        "Preliminary evidence-coverage assessment, not an advertising performance score",

      scores,

      aiAnalysis: analysis,

      processingStatus: "CQI analysis completed"
    }
  };
});

