const aiItems = $input.all();
const originalItems = $("09 – Explainable Creative Quality Index").all();

if (!aiItems.length) {
  throw new Error("No AI scoring responses received.");
}

if (aiItems.length !== originalItems.length) {
  throw new Error(
    `Mismatch: received ${aiItems.length} AI responses for ${originalItems.length} advertisements.`
  );
}

const criteria = [
  { key: "hook_strength", label: "Hook strength", weight: 25 },
  { key: "message_clarity", label: "Message clarity", weight: 20 },
  { key: "persuasiveness", label: "Persuasiveness", weight: 20 },
  { key: "cta_effectiveness", label: "CTA effectiveness", weight: 15 },
  { key: "creative_execution", label: "Creative execution", weight: 10 },
  { key: "audience_relevance", label: "Audience relevance", weight: 10 }
];

const aliases = {
  hook_strength: ["Hook strength"],
  message_clarity: ["Message clarity"],
  persuasiveness: ["Persuasiveness", "Persuiveness"],
  cta_effectiveness: ["CTA effectiveness"],
  creative_execution: ["Creative execution"],
  audience_relevance: ["Audience relevance"]
};

return aiItems.map((item, index) => {
  const input = item.json;
  const original = originalItems[index].json;

  // Extract AI response
  let content = input.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error(
      `AI scoring response content is missing for advertisement ${index + 1}.`
    );
  }

  // Parse JSON response
  if (typeof content === "string") {
    content = content
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();

    try {
      content = JSON.parse(content);
    } catch (error) {
      throw new Error(
        `Unable to parse AI scoring response for advertisement ${index + 1}: ${error.message}`
      );
    }
  }

  const aiRatings = content.ratings || {};

  let weightedTotal = 0;
  let availableWeight = 0;

  const ratings = criteria.map(criterion => {
    let rating = aiRatings[criterion.key];

    if (rating === undefined) {
      for (const alias of aliases[criterion.key]) {
        if (aiRatings[alias] !== undefined) {
          rating = aiRatings[alias];
          break;
        }
      }
    }

    const score =
      typeof rating === "number"
        ? rating
        : rating?.score;

    const valid =
      typeof score === "number" &&
      Number.isFinite(score) &&
      score >= 1 &&
      score <= 5;

    if (valid) {
      weightedTotal += score * criterion.weight;
      availableWeight += criterion.weight;
    }

    return {
      criterion: criterion.label,
      weight: criterion.weight,
      score: valid ? score : null,
      explanation:
        content.score_explanations?.[criterion.label] ||
        rating?.explanation ||
        "No separate explanation provided.",
      improvement:
        content.improvements || []
    };
  });

  // Weighted average of available ratings
  const finalScore =
    availableWeight > 0
      ? Number((weightedTotal / availableWeight).toFixed(2))
      : null;

  const finalCQI =
    finalScore !== null
      ? Number(((finalScore / 5) * 100).toFixed(2))
      : null;

  return {
    json: {
      project: "AdMind",
      adNumber: original.adNumber || index + 1,
      brand: original.brand,
      advertiser: original.advertiser,
      adId: original.adId,
      headline: original.headline,
      adFormat: original.adFormat,
      adLibraryUrl: original.adLibraryUrl,
      marketingObjective: original.marketingObjective,

      creativeQualityScore: finalScore,
      creativeQualityIndex: finalCQI,
      maximumScore: 100,

      availableWeight,
      unavailableWeight: 100 - availableWeight,
      evidenceCoverage: availableWeight,

      ratings,

      overallAssessment: content.overall_assessment || "",
      scoreExplanations: content.score_explanations || {},
      limitations: content.limitations || [],
      improvements: content.improvements || [],
      scoringNote: content.scoring_note || "",

      scoringMethod:
        "Weighted average of available AI ratings, normalized to 100",

      processingStatus: "Final CQI calculated"
    }
  };
});

const items = $input.all();

if (items.length === 0) {
  throw new Error("No scored advertisements received.");
}

// Sort by CQI, highest first
const rankedAds = items
  .map(item => item.json)
  .filter(ad => typeof ad.creativeQualityIndex === "number")
  .sort((a, b) => b.creativeQualityIndex - a.creativeQualityIndex);

if (rankedAds.length === 0) {
  throw new Error("No advertisements have a valid CQI score.");
}

// Assign competition ranks: equal scores receive equal ranks
let previousScore = null;
let currentRank = 0;

const results = rankedAds.map((ad, index) => {
  if (ad.creativeQualityIndex !== previousScore) {
    currentRank = index + 1;
    previousScore = ad.creativeQualityIndex;
  }

  return {
    ...ad,
    rank: currentRank,
    rankingStatus: currentRank === 1
      ? "Joint highest-scoring creative"
      : "Ranked"
  };
});

// Identify all advertisements tied for first place
const topScore = results[0].creativeQualityIndex;

const coWinners = results.filter(
  ad => ad.creativeQualityIndex === topScore
);

const winner = {
  advertiser: coWinners.map(ad => ad.advertiser).join(" and "),
  creativeQualityIndex: topScore,
  tied: coWinners.length > 1,
  coWinnerCount: coWinners.length,
  advertisements: coWinners.map(ad => ({
    advertiser: ad.advertiser,
    adId: ad.adId,
    headline: ad.headline,
    creativeQualityScore: ad.creativeQualityScore,
    creativeQualityIndex: ad.creativeQualityIndex,
    evidenceCoverage: ad.evidenceCoverage,
    adLibraryUrl: ad.adLibraryUrl
  }))
};

return [
  {
    json: {
      project: "AdMind",
      totalAdsAnalysed: results.length,
      rankingMethod: "Descending order by Creative Quality Index (CQI), with equal scores receiving equal ranks",
      winner,
      coWinners,
      rankedAds: results,
      winnerConclusion: coWinners.length > 1
        ? `${coWinners.length} advertisements are jointly highest-scoring with a CQI of ${topScore}/100.`
        : `${winner.advertiser} has the highest creative quality score of ${topScore}/100.`,
      performanceDisclaimer:
        "This ranking measures creative quality based on available evidence. It does not establish actual advertising performance.",
      processingStatus: "Advertisements ranked successfully"
    }
  }
];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content;

if (!content) {
  throw new Error("No strategy content received from the AI node.");
}

const cleaned = content
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let strategy;

try {
  strategy = JSON.parse(cleaned);
} catch (error) {
  throw new Error("Could not parse competitor strategy JSON: " + error.message);
}

if (!Array.isArray(strategy.competitor_comparison) ||
    strategy.competitor_comparison.length !== 4) {
  throw new Error("Expected exactly four competitor comparisons.");
}

if (!Array.isArray(strategy.suggested_campaign_ideas) ||
    strategy.suggested_campaign_ideas.length !== 3) {
  throw new Error("Expected exactly three campaign concepts.");
}

// Correct claims using the supplied research evidence.
for (const competitor of strategy.competitor_comparison) {
  if (competitor.competitor === "Cambly") {
    competitor.creative_weaknesses =
      "CTA was not supplied in the research evidence; visual execution was not independently inspected.";
    competitor.evidence_limitations =
      "CTA and detailed visual execution were not available for assessment.";
  }

  if (competitor.competitor === "Babbel") {
    competitor.creative_weaknesses =
      "Persuasive evidence and detailed visual execution were not fully available for assessment.";
    competitor.evidence_limitations =
      "The supplied evidence includes a CTA, but the full creative execution was not independently inspected.";
  }

  if (competitor.competitor === "Duolingo") {
    competitor.creative_strengths =
      "The supplied headline uses a clear brand-positioning claim.";
    competitor.creative_weaknesses =
      "Primary ad text was not verified, and the full video was not independently inspected.";
    competitor.evidence_limitations =
      "Primary text and detailed video content were not verified.";
  }

  if (competitor.competitor === "Hello English Online") {
    competitor.evidence_limitations =
      "No separate headline was supplied; detailed visual execution was not independently inspected.";
  }
}

// Replace the unsupported metrics recommendation.
strategy.opportunity_for_mysivi =
  (strategy.opportunity_for_mysivi || []).map(item =>
    item.includes("high usage metrics")
      ? "Recommendation: Showcase verified learner outcomes or testimonials only when reliable evidence is available."
      : item
  );

// Explicitly mark proposed features as unverified.
strategy.campaign_concept_disclaimer =
  "All three concepts are strategic hypotheses, not confirmed MySivi capabilities. Verify product features, pricing, availability and offers before publishing.";

strategy.suggested_campaign_ideas =
  strategy.suggested_campaign_ideas.map(idea => ({
    ...idea,
    verification_required: [
      "Verify that the proposed product features exist.",
      "Confirm pricing, availability and any free-trial offer.",
      "Approve all claims before using the concept in advertising."
    ]
  }));

strategy.evidence_limitations = [
  ...(strategy.evidence_limitations || []),
  "Campaign concepts contain proposed features that require MySivi verification.",
  "CQI measures assessed creative quality, not actual advertising performance."
];

const rankingData = $("12 – Rank Ads & Identify Winner").first().json;

return [{
  json: {
    ...rankingData,
    strategy,
    strategyParsingStatus: "Parsed and evidence corrections applied"
  }
}];

