const response = $input.first().json;

const content = response.choices?.[0]?.message?.content;

if (!content) {
  throw new Error("No creative concepts received from AI.");
}

const cleaned = content
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error("Invalid creative concepts JSON: " + error.message);
}

if (
  !Array.isArray(parsed.creative_concepts) ||
  parsed.creative_concepts.length !== 3
) {
  throw new Error("Expected exactly 3 creative concepts.");
}

const previousData =
  $("14 – Parse Competitor Strategy").first().json;

return [
  {
    json: {
      ...previousData,
      creativeConcepts: parsed.creative_concepts,
      creativeConceptCount: parsed.creative_concepts.length,
      creativeConceptParsingStatus: "Successfully parsed"
    }
  }
];

const conceptsData = $("16 – Parse Creative Concepts").first().json;
const strategyData = $("14 – Parse Competitor Strategy").first().json;
const rankingData = $("12 – Rank Ads & Identify Winner").first().json;
const scoringItems = $("11 – Parse AI Scores & Calculate Final CQI").all();
const dnaItems = $("09 – Explainable Creative Quality Index").all();

const concepts = conceptsData.creativeConcepts || [];
const strategy = strategyData.strategy || {};
const rankedAds = rankingData.rankedAds || [];

const scoreCoverage = rankedAds.map(ad => ({
  advertiser: ad.advertiser,
  cqi: ad.creativeQualityIndex,
  scoringCoverage: ad.evidenceCoverage ?? null
}));

const report = {
  reportTitle: "AdMind – Competitor Advertising Intelligence Report",
  brand: "MySivi",
  reportDate: new Date().toISOString().split("T")[0],

  executiveSummary: {
    objective: "Analyze four manually collected competitor advertisements, assess their creative quality, identify competitor messaging patterns, and recommend testable advertising concepts for MySivi.",
    competitorsAnalyzed: rankedAds.map(ad => ad.advertiser),
    advertisementsAnalyzed: rankedAds.length,
    highestScoringAds: rankingData.coWinners || [],
    keyFinding: rankingData.winnerConclusion || "See the competitor rankings and strategy analysis.",
    performanceDisclaimer: "The highest CQI represents the highest-scoring creative in this sample, not the best-performing advertising campaign."
  },

  competitorRankings: rankedAds.map(ad => ({
    rank: ad.rank,
    advertiser: ad.advertiser,
    adId: ad.adId,
    headline: ad.headline,
    adFormat: ad.adFormat,
    creativeQualityScore: ad.creativeQualityScore,
    creativeQualityIndex: ad.creativeQualityIndex,
    scoringCoverage: ad.evidenceCoverage ?? null,
    adLibraryUrl: ad.adLibraryUrl,
    marketingObjective: ad.marketingObjective
  })),

  scoringMethodology: {
    method: "Weighted AI-assisted creative quality assessment.",
    criteria: [
      { criterion: "Hook strength", weight: 25 },
      { criterion: "Message clarity", weight: 20 },
      { criterion: "Persuasiveness", weight: 20 },
      { criterion: "CTA effectiveness", weight: 15 },
      { criterion: "Creative execution", weight: 10 },
      { criterion: "Audience relevance", weight: 10 }
    ],
    calculation: "Available criterion ratings are weighted and normalized to a score out of 100. Unavailable criterion weights are excluded from the denominator.",
    coverageNote: "Scoring coverage indicates the percentage of rubric weight with numeric ratings. It does not mean all advertisement information was independently verified."
  },

  competitorStrategy: strategy,

  creativeAssessments: scoringItems.map(item => {
    const ad = item.json;
    return {
      advertiser: ad.advertiser,
      adId: ad.adId,
      creativeQualityScore: ad.creativeQualityScore,
      creativeQualityIndex: ad.creativeQualityIndex,
      scoringCoverage: ad.evidenceCoverage ?? null,
      ratings: ad.ratings || [],
      overallAssessment: ad.overallAssessment || "",
      limitations: ad.limitations || [],
      improvements: ad.improvements || []
    };
  }),

  creativeDNAAnalysis: dnaItems.map(item => ({
    advertiser: item.json.ad?.advertiser || item.json.advertiser || "Unknown",
    analysis: item.json.aiAnalysis || {}
  })),

  mySiviCreativeConcepts: concepts,

  strategicRecommendations: {
    recommendation: "Select a campaign concept for a small validation test only after confirming the target audience, product capabilities, offer, and messaging.",
    conceptDisclaimer: "The generated campaign concepts are proposals, not confirmation that MySivi currently offers the described features.",
    researchLimitations: strategy.researchLimitations || []
  },

  methodology: {
    dataSource: "Manual Meta Ad Library research using four supplied advertisement records. No automated Meta Ad Library API or Apify collection was used.",
    analysisMethod: "AI-assisted creative DNA analysis, weighted creative quality scoring, competitor strategy interpretation, and campaign concept generation.",
    researchScope: "Four manually collected advertisements from Duolingo, Cambly, Hello English Online, and Babbel.",
    dataLimitations: [
      "The analysis covers four supplied advertisements and is not a complete review of each competitor's advertising activity.",
      "Duolingo primary ad text and CTA were not verified.",
      "A separate headline was not supplied for Hello English Online.",
      "Cambly's supplied headline is in Portuguese.",
      "Ad images and videos were not independently inspected; creative descriptions are based on researcher observations.",
      "The form's target country was India, but the target country of each individual advertisement was not independently verified.",
      "No impressions, reach, advertising spend, click-through rates, installs, or conversion data were collected.",
      "Scoring coverage measures available rubric ratings, not completeness or independent verification of source evidence.",
      "MySivi product features, pricing, offers, and campaign capabilities have not been independently verified.",
      "Generated MySivi concepts are recommendations and must not be interpreted as existing product features.",
      "CQI is an analytical assessment of creative materials, not a measure of actual advertising performance."
    ]
  },

  reportStatus: "Generated – four-ad analysis; source and product claims require verification"
};

return [{
  json: {
    project: "AdMind",
    report,
    processingStatus: "Four-ad final research report generated",
    validation: {
      adsIncluded: rankedAds.length,
      conceptsIncluded: concepts.length,
      strategyIncluded: Object.keys(strategy).length > 0
    }
  }
}];

const input = $input.first().json;
const report = input.report;

if (!report) {
  throw new Error("Final report data is missing. Check the connection from Node 17.");
}

function esc(value) {
  if (value === null || value === undefined || value === "") {
    return "Not available";
  }

  if (typeof value === "object") {
    return esc(JSON.stringify(value));
  }

  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function list(items) {
  if (!Array.isArray(items) || !items.length) {
    return "<p>Not available</p>";
  }

  return "<ul>" + items.map(item =>
    `<li>${esc(item)}</li>`
  ).join("") + "</ul>";
}

const summary = report.executiveSummary || {};
const rankings = report.competitorRankings || [];
const methodology = report.methodology || {};
const scoring = report.scoringMethodology || {};
const strategy = report.competitorStrategy || {};
const concepts = report.mySiviCreativeConcepts || [];
const assessments = report.creativeAssessments || [];
const dnaItems = report.creativeDNAAnalysis || [];

const winnerNames = (summary.highestScoringAds || [])
  .map(ad => ad.advertiser)
  .filter(Boolean);

const rankingRows = rankings.map(ad => `
  <tr>
    <td>${esc(ad.rank)}</td>
    <td>${esc(ad.advertiser)}</td>
    <td>${esc(ad.creativeQualityIndex)}</td>
    <td>${esc(ad.scoringCoverage)}%</td>
    <td>${esc(ad.adFormat)}</td>
    <td><a href="${esc(ad.adLibraryUrl)}">View Ad</a></td>
  </tr>
`).join("");

const strategyRows = (strategy.competitor_comparison || []).map(item => `
  <tr>
    <td>${esc(item.competitor)}</td>
    <td>${esc(item.marketing_angle)}</td>
    <td>${esc(item.target_audience)}</td>
    <td>${esc(item.key_message)}</td>
    <td>${esc(item.cqi)}</td>
    <td>${esc(item.evidence_coverage)}%</td>
  </tr>
`).join("");

const assessmentHTML = assessments.map(ad => `
  <div class="concept">
    <h3>${esc(ad.advertiser)} – CQI ${esc(ad.creativeQualityIndex)}/100</h3>
    <p><strong>Scoring coverage:</strong> ${esc(ad.scoringCoverage)}%</p>
    <p><strong>Assessment:</strong> ${esc(ad.overallAssessment)}</p>

    <table>
      <thead>
        <tr>
          <th>Criterion</th>
          <th>Weight</th>
          <th>Rating</th>
          <th>Explanation</th>
        </tr>
      </thead>
      <tbody>
        ${(ad.ratings || []).map(r => `
          <tr>
            <td>${esc(r.criterion)}</td>
            <td>${esc(r.weight)}%</td>
            <td>${r.score == null ? "Not scored" : esc(r.score) + "/5"}</td>
            <td>${esc(r.explanation)}</td>
          </tr>
        `).join("")}
      </tbody>
    </table>

    <p><strong>Limitations:</strong></p>
    ${Array.isArray(ad.limitations) ? list(ad.limitations) : `<p>${esc(ad.limitations)}</p>`}

    <p><strong>Suggested improvements:</strong></p>
    ${list(ad.improvements)}
  </div>
`).join("");

const dnaHTML = dnaItems.map(item => {
  const dna = item.analysis || {};

  return `
    <div class="concept">
      <h3>${esc(dna.brand || item.advertiser)}</h3>
      <p><strong>Hook:</strong> ${esc(dna.hook)}</p>
      <p><strong>Core message:</strong> ${esc(dna.core_message)}</p>
      <p><strong>CTA:</strong> ${esc(dna.cta)}</p>
      <p><strong>Audience pain point:</strong> ${esc(dna.audience_pain_point)}</p>
      <p><strong>Emotional appeal:</strong> ${esc(dna.emotional_appeal)}</p>
      <p><strong>Marketing angle:</strong> ${esc(dna.marketing_angle)}</p>
      <p><strong>Funnel stage:</strong> ${esc(dna.funnel_stage)}</p>

      <h4>Strengths</h4>
      ${list(dna.strengths)}

      <h4>Weaknesses</h4>
      ${list(dna.weaknesses)}

      <h4>Improvement suggestions</h4>
      ${list(dna.improvement_suggestions)}
    </div>
  `;
}).join("");

const conceptHTML = concepts.map((c, index) => `
  <div class="concept">
    <h3>${index + 1}. ${esc(c.concept_name)}</h3>

    <p><strong>Target audience:</strong> ${esc(c.target_audience)}</p>
    <p><strong>Hook:</strong> ${esc(c.hook)}</p>
    <p><strong>Headline:</strong> ${esc(c.headline)}</p>
    <p><strong>Primary text:</strong> ${esc(c.primary_text)}</p>
    <p><strong>Visual direction:</strong> ${esc(c.visual_direction)}</p>
    <p><strong>Proposed CTA:</strong> ${esc(c.CTA)}</p>
    <p><strong>Rationale:</strong> ${esc(c.rationale)}</p>

    <p><strong>Features to verify before publishing:</strong></p>
    ${list(c.features_to_verify)}

    <p class="note">
      This is a proposed advertising concept. It does not confirm that
      MySivi currently provides these features or services.
    </p>
  </div>
`).join("");

const conceptIdeas = strategy.suggested_campaign_ideas || [];

const strategyIdeasHTML = conceptIdeas.map(item => `
  <div class="concept">
    <h3>${esc(item.concept)}</h3>
    <p><strong>Target audience:</strong> ${esc(item.target_audience)}</p>
    <p><strong>Hook:</strong> ${esc(item.hook)}</p>
    <p><strong>Key message:</strong> ${esc(item.key_message)}</p>
    <p><strong>Suggested CTA:</strong> ${esc(item.suggested_cta)}</p>
    <p><strong>Rationale:</strong> ${esc(item.rationale)}</p>
    <p><strong>Verification required:</strong></p>
    ${list(item.verification_required)}
  </div>
`).join("");

const html = `<!DOCTYPE html>
