.score {
  background: #eff6ff;
  padding: 20px;
  margin: 20px 0;
  border-radius: 8px;
}

.score strong {
  font-size: 32px;
  color: #1d4ed8;
}

.concept {
  border: 1px solid #dbe3ef;
  padding: 20px;
  margin: 20px 0;
  border-radius: 8px;
  page-break-inside: avoid;
}

.note {
  color: #92400e;
